    for name in ('predict','external_only','observe','loss_and_gradients','_forward'):
        setattr(cls,name,forbidden)
started=time.perf_counter()
fixture,inputs,parent,archive,custody=state.load_state()
cores={a:state.restore_core(parent,archive,a) for a in state.AFTER_A}
