try:state.restore_core(parent,bad,'trainable')
except ValueError as e:errors['tampered_weight']=str(e)
else:raise AssertionError('tampered weights accepted')
changed=copy.deepcopy(parent['checkpoints']['after_A']['trainable']);changed['offer_count']+=1
try:state.restore_core({'checkpoints':{'after_A':{'trainable':changed}}},archive,'trainable')
