try:state.restore_core(parent,bad,'trainable')
except ValueError as e:errors['tampered_Adam_step']=str(e)
else:raise AssertionError('tampered step accepted')
try:state.restore_core(parent,archive,'frozen')
except ValueError as e:errors['mode_relabel']=str(e)
else:raise AssertionError('unapproved source arm accepted')
assert all(core.checkpoint_sha256==state.AFTER_A[a] for a,core in cores.items())
